content:
:root {
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --danger-color: #ef4444;
  --danger-hover: #dc2626;
  --bg-color: #f3f4f6;
  --card-bg: #ffffff;
  --text-main: #1f2937;
  --text-sub: #4b5563;
  --border-color: #d1d5db;
  --error-color: #dc2626;
}

@media (prefers-color-scheme: dark) {
  :root {
    --primary-color: #60a5fa;
    --primary-hover: #3b82f6;
    --danger-color: #f87171;
    --danger-hover: #ef4444;
    --bg-color: #0f172a;
    --card-bg: #1e293b;
    --text-main: #f8fafc;
    --text-sub: #94a3b8;
    --border-color: #334155;
    --error-color: #f87171;
  }

  .result-box {
    background-color: #1e293b !important;
    border-color: #334155 !important;
  }

  .history-item {
    background-color: #1e293b !important;
    border-color: #334155 !important;
  }

  .reference-table th,
  .reference-table td {
    border-bottom-color: #334155 !important;
  }
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
}

/* スクロールバーのスタイリング */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: var(--bg-color);
}

::-webkit-scrollbar-thumb {
  background: var(--border-color);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--text-sub);
}

/* アクセシビリティ向上のためのフォーカススタイル */
a:focus-visible,
button:focus-visible,
input:focus-visible {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
}

.app-container {
  max-width: 600px;
  margin: 2rem auto;
  padding: 0 1rem;
}

.card {
  background-color: var(--card-bg);
  border-radius: 12px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  padding: 2rem;
  margin-bottom: 1.5rem;
}

.title {
  font-size: 1.75rem;
  font-weight: 700;
  text-align: center;
  margin-bottom: 1.5rem;
  color: var(--text-main);
}

.input-group {
  margin-bottom: 1.25rem;
}

.label {
  display: block;
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
  color: var(--text-sub);
}

.input {
  width: 100%;
  padding: 0.75rem;
  font-size: 1rem;
  background-color: var(--card-bg);
  color: var(--text-main);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.input:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.btn {
  display: inline-block;
  width: 100%;
  padding: 0.75rem 1rem;
  font-size: 1rem;
  font-weight: 600;
  text-align: center;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: var(--primary-color);
  color: white;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.btn-danger {
  background-color: var(--danger-color);
  color: white;
  padding: 0.35rem 0.75rem;
  font-size: 0.875rem;
  width: auto;
}

.btn-danger:hover {
  background-color: var(--danger-hover);
}

.error-text {
  color: var(--error-color);
  font-size: 0.875rem;
  margin-top: 0.5rem;
}

.result-box {
  background-color: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 1.5rem;
  text-align: center;
  margin-top: 1.5rem;
}

.bmi-value {
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--primary-color);
  margin-bottom: 0.5rem;
}

.bmi-category {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 1rem;
  color: var(--text-main);
}

.reference-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 1rem;
  font-size: 0.875rem;
  text-align: left;
  color: var(--text-main);
}

.reference-table th,
.reference-table td {
  padding: 0.5rem;
  border-bottom: 1px solid #e2e8f0;
}

.reference-table th {
  font-weight: 600;
  color: var(--text-sub);
}

.history-section {
  margin-top: 2rem;
}

.history-list {
  list-style: none;
  margin-top: 1rem;
  max-height: 300px;
  overflow-y: auto;
}

.history-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.75rem;
  border-bottom: 1px solid #e2e8f0;
  background-color: #fff;
  border-radius: 6px;
  margin-bottom: 0.5rem;
  color: var(--text-main);
}

.history-item:last-child {
  border-bottom: 1px solid #e2e8f0;
}

@media (max-width: 480px) {
  .card {
    padding: 1.25rem;
  }

  .title {
    font-size: 1.5rem;
  }

  .bmi-value {
    font-size: 2rem;
  }
}

export type UnitSystem = "metric" | "imperial";

export interface BmiRecord {
  id: string;
  height: number;
  weight: number;
  bmi: number;
  category: string;
  date: string;
  unit?: UnitSystem;
}

export interface BmiFormProps {
  height: string;
  weight: string;
  onHeightChange: (val: string) => void;
  onWeightChange: (val: string) => void;
  onSubmit: (e: React.FormEvent) => void;
  error: string;
  unit?: UnitSystem;
  onUnitChange?: (unit: UnitSystem) => void;
}

export interface BmiResultProps {
  record: BmiRecord | null;
}

export interface BmiHistoryProps {
  records: BmiRecord[];
  onDelete: (id: string) => void;
  onClear: () => void;
}

import { BmiFormProps } from "../types";

export default function BmiForm({
  height,
  weight,
  onHeightChange,
  onWeightChange,
  onSubmit,
  error,
}: BmiFormProps) {
  return (
    <form onSubmit={onSubmit}>
      <div className="input-group">
        <label className="label" htmlFor="height-input">
          身長 (cm)
        </label>
        <input
          id="height-input"
          type="number"
          step="0.1"
          min="1"
          max="300"
          placeholder="例: 170"
          value={height}
          onChange={(e) => onHeightChange(e.target.value)}
          className="input"
          aria-invalid={!!error}
          aria-describedby={error ? "bmi-error-text" : undefined}
        />
      </div>

      <div className="input-group">
        <label className="label" htmlFor="weight-input">
          体重 (kg)
        </label>
        <input
          id="weight-input"
          type="number"
          step="0.1"
          min="1"
          max="500"
          placeholder="例: 65"
          value={weight}
          onChange={(e) => onWeightChange(e.target.value)}
          className="input"
          aria-invalid={!!error}
          aria-describedby={error ? "bmi-error-text" : undefined}
        />
      </div>

      {error && <div id="bmi-error-text" className="error-text">{error}</div>}

      <button type="submit" className="btn btn-primary" style={{ marginTop: "1rem" }}>
        BMIを計算する
      </button>
    </form>
  );
}

import { BmiHistoryProps } from "../types";

export default function BmiHistory({ records = [], onDelete, onClear }: BmiHistoryProps) {
  if (!records || records.length === 0) return null;

  const handleClearClick = () => {
    if (window.confirm("すべての履歴を削除してもよろしいですか？")) {
      onClear();
    }
  };

  return (
    <div className="history-section">
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <h3 style={{ fontSize: "1.25rem", fontWeight: 600 }}>計算履歴</h3>
        <button type="button" className="btn btn-danger" onClick={handleClearClick}>
          履歴を全クリア
        </button>
      </div>

      <ul className="history-list">
        {records.map((item) => (
          <li key={item.id} className="history-item">
            <div>
              <div style={{ fontWeight: 600 }}>
                BMI: {item.bmi.toFixed(1)} ({item.category})
              </div>
              <div style={{ fontSize: "0.75rem", color: "var(--text-sub)" }}>
                {item.height}cm / {item.weight}kg - {item.date}
              </div>
            </div>
            <button
              type="button"
              className="btn btn-danger"
              onClick={() => onDelete(item.id)}
              aria-label={`${item.date}の記録を削除`}
            >
              削除
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useState, useEffect, FormEvent } from "react";
import { BmiRecord } from "./types";
import BmiForm from "./components/BmiForm";
import BmiResult from "./components/BmiResult";
import BmiHistory from "./components/BmiHistory";
import "./index.css";

export default function App() {
  const [height, setHeight] = useState<string>("");
  const [weight, setWeight] = useState<string>("");
  const [error, setError] = useState<string>("");
  const [currentRecord, setCurrentRecord] = useState<BmiRecord | null>(null);
  const [records, setRecords] = useState<BmiRecord[]>([]);

  useEffect(() => {
    try {
      const saved = localStorage.getItem("bmi_records");
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed)) {
          setRecords(parsed);
        }
      }
    } catch {
      setError("保存された履歴の読み込みに失敗しました。");
    }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem("bmi_records", JSON.stringify(records));
    } catch {
      setError("履歴の保存に失敗しました。");
    }
  }, [records]);

  const calculateCategory = (bmi: number): string => {
    if (bmi < 18.5) return "低体重 (18.5未満)";
    if (bmi < 25) return "普通体重 (18.5〜25未満)";
    if (bmi < 30) return "肥満 (度1) (25〜30未満)";
    return "肥満 (度2以上) (30以上)";
  };

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    setError("");

    const hNum = parseFloat(height);
    const wNum = parseFloat(weight);

    if (!height || !weight || isNaN(hNum) || isNaN(wNum)) {
      setError("身長と体重を正しく入力してください。");
      return;
    }

    if (hNum < 1 || hNum > 300 || wNum < 1 || wNum > 500) {
      setError("身長は1cm〜300cm、体重は1kg〜500kgの範囲で入力してください。");
      return;
    }

    const heightInMeters = hNum / 100;
    const bmi = wNum / (heightInMeters * heightInMeters);
    const category = calculateCategory(bmi);
    const date = new Date().toLocaleDateString("ja-JP", {
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
    });

    const newRecord: BmiRecord = {
      id: Date.now().toString(),
      height: hNum,
      weight: wNum,
      bmi,
      category,
      date,
    };

    setCurrentRecord(newRecord);
    setRecords((prev) => [newRecord, ...(Array.isArray(prev) ? prev : [])]);
  };

  const handleDelete = (id: string) => {
    setRecords((prev) => (Array.isArray(prev) ? prev.filter((r) => r.id !== id) : []));
    if (currentRecord?.id === id) {
      setCurrentRecord(null);
    }
  };

  const handleClear = () => {
    setRecords([]);
    setCurrentRecord(null);
  };

  return (
    <div className="app-container">
      <div className="card">
        <h1 className="title">BMI計算ツール</h1>
        <BmiForm
          height={height}
          weight={weight}
          onHeightChange={setHeight}
          onWeightChange={setWeight}
          onSubmit={handleSubmit}
          error={error}
        />
        <BmiResult record={currentRecord} />
        <BmiHistory
          records={records}
          onDelete={handleDelete}
          onClear={handleClear}
        />
      </div>
    </div>
  );
}
